using Microsoft.Dynamics365.LocalizationFramework;
using Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Blob;
using Microsoft.WindowsAzure.Storage.Auth;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERFileSourceAzureStorage</c> manages the ER file source for 'MET Azure Storage'
/// </summary>
internal final class METERFileSourceAzureStorage implements ERIFileSource
{
    private Set docuTypesSet;
    str fileMask;
    boolean isDecrypted;

    private const str FileDateTimeFormat = 'yyyy-MM-ddTHH:mm:ssZ';

}

Method.Source:
/// <summary>
/// Creates a new instance of <C>METERFileSourceAzureStorage</C>.
/// </summary>
/// <param name = "_docuTypesSet">A document type set.</param>
/// <param name = "_fileMask">A file mask to filter; optional.</param>
/// <param name = "_isDecrypted">Use Azure function for decrypt file</param>
protected void new(Set _docuTypesSet, str _fileMask, boolean _isDecrypted)
{
    docuTypesSet = _docuTypesSet;
    fileMask = _fileMask;
    isDecrypted = _isDecrypted;
    if (docuTypesSet.empty())
    {
        throw error("@MET:DocuTypeAzureStorageRequired");
    }
}

/// <summary>
/// Construct new instance of <c>METERFileSourceAzureStorage</c>.
/// </summary>
/// <param name = "_docuTypesSet">A document type set.</param>
/// <param name = "_fileMask">A file mask to filter; optional.</param>
/// <param name = "_isDecrypted">Use Azure function for decrypt file</param>
/// <returns>New instance of class.</returns>
internal static METERFileSourceAzureStorage construct(Set _docuTypesSet, str _fileMask, boolean _isDecrypted)
{
    return new METERFileSourceAzureStorage(_docuTypesSet, _fileMask, _isDecrypted);
}

/// <summary>
/// Get files from multiple document types as multi select is enabled
/// </summary>
/// <returns>ERIFiles</returns>
[Hookable(false)]
public ERIFiles GetFiles()
{
    var ret = new ERFiles();        
    var i = docuTypesSet.getEnumerator();
    while (i.moveNext())
    {
        DocuType docuType = DocuType::find(i.current());
        if (docuType)
        {
            if (docuType.FilePlace != DocuFilePlace::METAzureStorage)
            {
                throw error(strFmt("@MET:DocuTypeAzureStorageValidation", i.current()));
            }
            this.appendFilesByDocuType(docuType, ret);
        }
    }
    return ret;
}

    /// <summary>
    /// Method to add files from blob storage 'file states for the sources'.
    /// Does not seem to process multiple files
    /// </summary>
    /// <param name = "_docuType">Document type</param>
    /// <param name = "_files">ERFiles</param>
    private void appendFilesByDocuType(DocuType _docuType, ERFiles _files)
    {    
        const str emptyStr = '';
        
        StorageCredentials credentials = new StorageCredentials(_docuType.METAzureStorageAccountName, _docuType.METAzureStorageSecret);
        CloudStorageAccount storageAccount = new CloudStorageAccount(credentials, true);

        CloudBlobClient blobClient = storageAccount.CreateCloudBlobClient();
           
        CloudBlobContainer rootContainer = blobClient.GetContainerReference(_docuType.METAzureStorageContainerName);

        //CloudBlobDirectory directory = rootContainer.GetDirectoryReference(_docuType.METAzureStorageFolder);
        

        System.Collections.IEnumerable list = new System.Collections.Generic.List<str>();
        list = rootContainer.ListBlobs(_docuType.METAzureStorageFolder, false, 0, null, null);
        System.Collections.IEnumerator listEnumerator = list.getEnumerator();

        while  (listEnumerator.moveNext())
        {
            CloudBlockBlob blob = listEnumerator.get_Current();

            //str fileurl = blob.StorageUri.PrimaryUri.AbsoluteUri;
            str fileName = strReplace(blob.Name, _docuType.METAzureStorageFolder, emptyStr);

            if (blob.Exists(null, null)
            && (!fileMask || ERFileNameUtils::IsMaskMatched(fileName, fileMask)))
            {                
                // find a way to get file created date time
                var file = METERFormatFileAzureStorage::construct(guid2Str(newGuid()), fileName, DateTimeUtil::getSystemDateTime(), blob.Name, blob, isDecrypted, _docuType);
            
                _files.Add(file);
            }
        }
    }
